import{_ as a,c as n,o as e,ag as p}from"./chunks/framework.CQuhCYrb.js";const b=JSON.parse('{"title":"RStudio Server Guide","description":"","frontmatter":{"title":"RStudio Server Guide"},"headers":[],"relativePath":"server-guides/rstudio-server-guide.md","filePath":"server-guides/rstudio-server-guide.md","lastUpdated":null}'),r={name:"server-guides/rstudio-server-guide.md"};function l(i,s,t,o,u,c){return e(),n("div",null,[...s[0]||(s[0]=[p(`<h1 id="rstudio-server-guide" tabindex="-1">RStudio Server Guide <a class="header-anchor" href="#rstudio-server-guide" aria-label="Permalink to &quot;RStudio Server Guide&quot;">​</a></h1><h2 id="rstudio-server-guide-1" tabindex="-1">RStudio Server Guide <a class="header-anchor" href="#rstudio-server-guide-1" aria-label="Permalink to &quot;RStudio Server Guide&quot;">​</a></h2><p>Return to <a href="/server-guides/">Guides</a> Return to [This guide is based on the <a href="/research/">https://davetang.org/muse/2021/04/24/running-rstudio-server-with-docker/ RStudio Server Guide</a>. It is designed to help you get started with RStudio Server, a web-based interface for R programming. RStudio Server allows you to run R and RStudio in a web browser, providing a flexible and accessible data analysis and visualization environment.</p><h3 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h3><ul><li><p>Docker installed on your system.</p></li><li><p>Basic understanding of Docker commands and R programming.</p></li></ul><h3 id="steps-to-set-up-rstudio-server-with-docker" tabindex="-1">Steps to Set Up RStudio Server with Docker <a class="header-anchor" href="#steps-to-set-up-rstudio-server-with-docker" aria-label="Permalink to &quot;Steps to Set Up RStudio Server with Docker&quot;">​</a></h3><h3 id="pull-the-rstudio-docker-image" tabindex="-1">Pull the RStudio Docker Image <a class="header-anchor" href="#pull-the-rstudio-docker-image" aria-label="Permalink to &quot;Pull the RStudio Docker Image&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>docker pull rocker/rstudio</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="create-a-dockerfile" tabindex="-1">Create a Dockerfile <a class="header-anchor" href="#create-a-dockerfile" aria-label="Permalink to &quot;Create a Dockerfile&quot;">​</a></h3><p>Include necessary system dependencies and R packages in your Dockerfile:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>FROM rocker/rstudio</span></span>
<span class="line"><span></span></span>
<span class="line"><span>RUN apt clean all &amp;&amp; \\</span></span>
<span class="line"><span>    apt update &amp;&amp; \\</span></span>
<span class="line"><span>    apt upgrade -y &amp;&amp; \\</span></span>
<span class="line"><span>    apt install -y \\</span></span>
<span class="line"><span>        libhdf5-dev \\</span></span>
<span class="line"><span>        libcurl4-gnutls-dev \\</span></span>
<span class="line"><span>        libssl-dev \\</span></span>
<span class="line"><span>        libxml2-dev \\</span></span>
<span class="line"><span>        libpng-dev \\</span></span>
<span class="line"><span>        libxt-dev \\</span></span>
<span class="line"><span>        zlib1g-dev \\</span></span>
<span class="line"><span>        libbz2-dev \\</span></span>
<span class="line"><span>        liblzma-dev \\</span></span>
<span class="line"><span>        libglpk40 \\</span></span>
<span class="line"><span>        libgit2-dev \\</span></span>
<span class="line"><span>    &amp;&amp; apt clean all &amp;&amp; \\</span></span>
<span class="line"><span>    apt purge &amp;&amp; \\</span></span>
<span class="line"><span>    rm -rf /var/lib/apt/lists/* /tmp/* /var/tmp/&#39;&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>RUN Rscript -e &quot;install.packages(c(&#39;rmarkdown&#39;, &#39;tidyverse&#39;, &#39;workflowr&#39;, &#39;shiny&#39;, &#39;blogdown&#39;, &#39;bookdown&#39;, &#39;learnr&#39;, &#39;xaringan&#39;, &#39;rticles&#39;, &#39;pkgdown&#39;, &#39;devtools&#39;, &#39;usethis&#39;, &#39;testthat&#39;, &#39;roxygen&#39;, &#39;rhub&#39;, &#39;covr&#39;, &#39;rmarkdown&#39;, &#39;knitr&#39;, &#39;dplyr&#39;, &#39;readr&#39;, &#39;packrat&#39;, &#39;rsconnect&#39;))&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>WORKDIR /home/rstudio</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br></div></div><h3 id="build-your-custom-docker-image" tabindex="-1">Build Your Custom Docker Image <a class="header-anchor" href="#build-your-custom-docker-image" aria-label="Permalink to &quot;Build Your Custom Docker Image&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>docker build -t my-rstudio .</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="run-your-custom-container" tabindex="-1">Run Your Custom Container <a class="header-anchor" href="#run-your-custom-container" aria-label="Permalink to &quot;Run Your Custom Container&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>docker run -d -p 8787:8787 -e PASSWORD=yourpassword my-rstudio</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="run-multiple-instances-optional" tabindex="-1">Run Multiple Instances (Optional) <a class="header-anchor" href="#run-multiple-instances-optional" aria-label="Permalink to &quot;Run Multiple Instances (Optional)&quot;">​</a></h3><p>You can run multiple RStudio Server instances for different users by specifying unique ports and credentials:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>docker run -d -p 8788:8787 -e USER=user1 -e PASSWORD=user1password my-rstudio</span></span>
<span class="line"><span>docker run -d -p 8789:8787 -e USER=user2 -e PASSWORD=user2password my-rstudio</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="combined-commands-for-quick-setup" tabindex="-1">Combined Commands for Quick Setup <a class="header-anchor" href="#combined-commands-for-quick-setup" aria-label="Permalink to &quot;Combined Commands for Quick Setup&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>docker pull rocker/rstudio</span></span>
<span class="line"><span>touch Dockerfile</span></span>
<span class="line"><span>echo &quot;FROM rocker/rstudio&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>echo &quot;RUN apt clean all &amp;&amp; \\\\&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>echo &quot;    apt update &amp;&amp; \\\\&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>echo &quot;    apt upgrade -y &amp;&amp; \\\\&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>echo &quot;    apt install -y \\\\&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>echo &quot;        libhdf5-dev \\\\&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>echo &quot;        libcurl4-gnutls-dev \\\\&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>echo &quot;        libssl-dev \\\\&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>echo &quot;        libxml2-dev \\\\&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>echo &quot;        libpng-dev \\\\&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>echo &quot;        libxt-dev \\\\&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>echo &quot;        zlib1g-dev \\\\&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>echo &quot;        libbz2-dev \\\\&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>echo &quot;        liblzma-dev \\\\&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>echo &quot;        libglpk40 \\\\&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>echo &quot;        libgit2-dev \\\\&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>echo &quot;    &amp;&amp; apt clean all &amp;&amp; \\\\&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>echo &quot;    apt purge &amp;&amp; \\\\&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>echo &quot;    rm -rf /var/lib/apt/lists/* /tmp/* /var/tmp/&#39;&#39;&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>echo &quot;RUN Rscript -e \\&quot;install.packages(c(&#39;rmarkdown&#39;, &#39;tidyverse&#39;, &#39;workflowr&#39;, &#39;shiny&#39;, &#39;blogdown&#39;, &#39;bookdown&#39;, &#39;learnr&#39;, &#39;xaringan&#39;, &#39;rticles&#39;, &#39;pkgdown&#39;, &#39;devtools&#39;, &#39;usethis&#39;, &#39;testthat&#39;, &#39;roxygen&#39;, &#39;rhub&#39;, &#39;covr&#39;, &#39;rmarkdown&#39;, &#39;knitr&#39;, &#39;dplyr&#39;, &#39;readr&#39;, &#39;packrat&#39;, &#39;rsconnect&#39;))\\&quot;&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>echo &quot;WORKDIR /home/rstudio&quot; &gt;&gt; Dockerfile</span></span>
<span class="line"><span>docker build -t my-rstudio .</span></span>
<span class="line"><span>docker run -d -p 8787:8787 -e PASSWORD=yourpassword my-rstudio</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br></div></div><h3 id="notes-and-references" tabindex="-1">Notes and References <a class="header-anchor" href="#notes-and-references" aria-label="Permalink to &quot;Notes and References&quot;">​</a></h3><ul><li><p>For more details, see the original source: <a href="https://davetang.org/muse/2021/04/24/running-rstudio-server-with-docker/" target="_blank" rel="noreferrer">Dave Tang&#39;s RStudio Guide</a>.</p></li><li><p>For more information on RStudio Server, visit <a href="https://www.rstudio.com/products/rstudio/rstudio-server/" target="_blank" rel="noreferrer">RStudio Server Official Site</a>.</p></li></ul>`,22)])])}const m=a(r,[["render",l]]);export{b as __pageData,m as default};
